class Events internal constructor(private val native: EventsNative) : AutoCloseable {
    private var closed = false

    enum class Result(val value: Int) {
        SUCCESS(0),
        NOT_AVAILABLE(1),
        CONNECTION_ERROR(2),
        UNSUPPORTED(3),
        DENIED(4),
        FAILED(5),
        TIMEOUT(6),
        NO_SYSTEM(7),
        UNKNOWN(8);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    enum class LogLevel(val value: Int) {
        EMERGENCY(0),
        ALERT(1),
        CRITICAL(2),
        ERROR(3),
        WARNING(4),
        NOTICE(5),
        INFO(6),
        DEBUG(7);

        companion object {
            fun fromValue(value: Int): LogLevel =
                entries.find { it.value == value } ?: entries.first()
        }
    }

    data class Event(
        val compid: Int,
        val message: String,
        val description: String,
        val logLevel: LogLevel,
        val eventNamespace: String,
        val eventName: String,
    )

